-- Generated by `chainindex dbt` from chains/base.yaml and abis/AerodromeCLFactory.json. Do not edit: change the chain file or ABI and regenerate.
-- PoolCreated(address,address,int24,address)
{{ config(
    materialized='view',
    schema='events_base',
    alias='aerodrome_cl_factory__pool_created',
    tags=['chains', 'chain_base'],
) }}

select
    toUInt64(8453) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as token0,
    concat('0x', substring(substring(topic2, 3, 64), 25, 40)) as token1,
    toInt32(reinterpretAsInt256(reverse(unhex(substring(topic3, 3, 64))))) as tick_spacing,
    concat('0x', substring(substring(data, 3, 64), 25, 40)) as pool
from {{ source('chain_base', 'logs') }}
where topic0 = '0xab0d57f0df537bb25e80245ef7748fa62353808c54d6e528a9dd20887aed9ac2'
  and address in (select address from {{ ref('base__contracts') }} where contract = 'aerodrome_cl_factory')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_base', 'orphaned_blocks') }}
  )
